-- netcare-pholoso-hospital-fauna-park (researched)
UPDATE businesses SET description = 'Netcare Pholoso Hospital is a private hospital in Fauna Park offering specialist and acute healthcare services to patients across Polokwane and the wider Limpopo region. Its emergency and trauma unit, maternity and neonatal care, paediatric ward and surgical teams work alongside a broad range of medical specialities, including cardiology, cardiothoracic surgery, ENT, general surgery, gynaecology, internal medicine, neurology, neurosurgery, oncology, ophthalmology, orthopaedic and spinal surgery, urology and vascular surgery, supported by theatres, a cardiac catheterisation unit, endoscopy and radiology services.

The 200-bed hospital was developed in partnership between Netcare and the Pholoso Hospital Group and opened in 2015. It holds Level II Trauma Centre accreditation from the Trauma Society of South Africa and has a helicopter landing pad for air-ambulance patients, allowing its emergency unit to provide round-the-clock, multidisciplinary care for serious and potentially life-threatening injuries, making it a key point of care for patients needing surgical, medical, maternity, paediatric and specialist treatment in the region.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.netcare.co.za/netcare-facilities/netcare-pholoso-hospital', '$[#]', 'https://www.saprivatehospitals.com/limpopo/pholoso-hospital-netcare-in-polokwane-limpopo/'), description_enriched_at = datetime('now') WHERE slug = 'netcare-pholoso-hospital-fauna-park' AND description = 'Netcare Pholoso Hospital is a 200-bed private hospital in Fauna Park offering specialist services including a maternity unit with a neonatal intensive care unit, a paediatric ward, and a 24-hour emergency unit with a helicopter landing pad, alongside surgical and medical specialties such as cardiology, orthopaedic surgery and general surgery.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
